get_dashboard_kpi_options.code:
var response = await client.DashboardKpis.GetDashboardKpiOptionsAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
Console.WriteLine($"{body["min"]} {body["max"]} {string.Join(", ", (IReadOnlyList<object?>)body["selected"]!)}");
foreach (var group in ((IReadOnlyList<object?>)body["groups"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{group["key"]} {group["label"]}");

get_dashboard_kpi_selection.code:
var response = await client.DashboardKpis.GetDashboardKpiSelectionAsync(
    new Dictionary<string, object?> { ["duration"] = "last_7_days" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var period = (IReadOnlyDictionary<string, object?>)body["period"]!;
Console.WriteLine($"{period["start_date"]} {period["end_date"]}");
foreach (var kpi in ((IReadOnlyList<object?>)body["selected"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{kpi["position"]} {kpi["key"]} {kpi["value"]} {kpi["previous_value"]}");

update_dashboard_kpi_selection.code:
var response = await client.DashboardKpis.UpdateDashboardKpiSelectionAsync(
    new Dictionary<string, object?> { ["metrics"] = new[] { "total_sales", "total_orders", "aov" } },
    new Dictionary<string, object?> { ["duration"] = "last_7_days" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var kpi in ((IReadOnlyList<object?>)body["selected"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{kpi["position"]} {kpi["key"]} {kpi["value"]} {kpi["previous_value"]}");
